	/** Specify whether a job sheet is required for the service. **Possible values**: Yes, No. */
	Job_Sheet_Required?: "Yes" | "No" | null;
	/** Specify the operational status of the service. **Possible values**: - Available - service is active and accepting bookings. - Not in Use - service is currently inactive. - Scheduled - service is queued to become Available on Available_From. - Temporarily Unavailable - service is paused for the… */
	Status?: "Available" | "Temporarily Unavailable" | "Not in Use" | "Scheduled" | null;
	Owner?: ZohoCrmOwnerBaseInput;
	/** Specify a description of the service. */
	Description?: string | null;
	/** Specify the available time windows for the service. The total available time must be at least equal to the service Duration. */
	Available_Timings?: string | null;
	/** Specify the name of the service. */
	Service_Name?: string | null;
	/** Specify the date from which the service is available, in YYYY-MM-DD format. The key is mandatory when Availability_Type is Specific Date Range. */
	Available_From?: string | null;
	/** Specify the date until which the service is available, in YYYY-MM-DD format. The key is mandatory when Availability_Type is Specific Date Range. */
	Available_Till?: "2026-01-13" | "2026-01-29" | null;
	/** Specify the list of business days on which the service is available. The key is mandatory when Availability_Type is Specific Day(s). */
	Available_Days?: Array<string> | null;
	/** Specify the taxes applied to the service cost. */
	Tax?: Array<string> | null;
	/** Specify the duration of the service, in minutes. Must be greater than 5 minutes and less than 24 hours. */
	Duration?: number | null;
	/** Specify the job sheet section associated with the service. It can be set only when Job_Sheet_Required is Yes. */
	Job_Sheet_Section__s?: string | null;
	/** Specify the date and time from which the service becomes unavailable. Must fall within the service availability window. */
	Unavailable_From?: string | null;
	/** Specify the record image to associate with the service. */
	Record_Image?: string | null;
	/** Specify the price charged for the service in the organization currency. */
	Price?: number | null;
	/** Specify the unique ID of the service record being updated. */
	id?: string | null;
	/** Specify the tag names to associate with the service record. Refer to the [Get tags](tags.yaml#$.paths./settings/tags.get) resource for valid values. */
	Tag?: Array<string> | null;
	/** Specify how the service availability is defined. **Possible values**: Specific Day(s), Specific Date Range, Every Business Days, Specific Date(s). */
	Availability_Type?: "Specific Day(s)" | "Specific Date Range" | "Every Business Days" | "Specific Date(s)" | null;
	/** Specify the list of dates on which the service is available. The key is mandatory when Availability_Type is Specific Date(s). */
	Available_Dates?: Array<string> | null;
