/** Represents an alternate representation of a transition to update, including its ID, name, description, module, trigger type, transition type, owners, criteria, during inputs, actions, and color code. */
export type ZohoCrmTransitionUpdateEntryAlternateInput = {
	/** Contains the layout associated with the transition's module. This property must accompany `during_inputs`; omitting it while providing `during_inputs` causes a misleading **INVALID_DATA** error referencing the `during_inputs[0]` field details. The object must include `id` and `api_name` at minimum. */
	layout?: {
		/** Represents the ID of the layout. */
		id: string;
		/** Represents the API name of the layout. */
		api_name: string;
		/** Represents the display name of the layout. */
		name?: string;
	};
	/** Contains the during-transition fields shown to the user. Entries are appended to the existing list on each PUT call instead of replacing it. To remove an entry, send it with `_delete: null` along with its `id`. Requires the `layout` property to be present in the same request body. */
	during_inputs?: Array<ZohoCrmTransitionDuringInputDescriptorAlternateInput> | null;
	/** This denotes the criteria of the transition to be created. */
	criteria?: ZohoCrmTransitionCriteriaDefinitionAlternateInput;
	/** Represents the trigger type of the transition to be created. Possible values: **automatic**, **manual**. */
	trigger_type?: "automatic" | "manual" | null;
	/** This denotes the module of the transition to be created */
	module?: ZohoCrmActionTargetModuleReferenceAlternate1Input;
	/** Represents the name of the transition to be created. Transition names inside a specific blueprint must be unique. */
	name?: string | null;
	/** Represents the description of the transition to be created. */
	description?: string | null;
	/** Represents the type of the transition to be created. Possible values: **standalone_transition**, **parallel_transition**, **child_transition**. */
	transition_type?: "standalone_transition" | "parallel_transition" | "child_transition" | null;
	/** Represents the owners of the transition to be created who are permitted to execute the transition. */
	owners?: Array<ZohoCrmTransitionOwnerAssignmentInputAlternateInput> | null;
	/** Represents the ID of the transition to be updated. */
	id: string;
	/** Contains the list of after actions of the transition to be created. */
	actions?: Array<ZohoCrmTransitionAfterActionEntryAlternateInput> | null;
	/** Represents the color code of the transition button to be created. Example: #F27E22. */
	color_code?: string | null;
};

