	details?: Record<string, ZohoCrmJsonValue> | null;
	/** Represents the type of unenrollment condition for the Cadence. Possible values: automatic_unenroll - Unenroll records automatically based on the configured condition. end_date - Unenroll records when the specified end date is reached. criteria - Unenroll records that meet the specified criteria.… */
	type: "automatic_unenroll" | "end_date" | "criteria" | "followup_criteria";
